// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Behaviour of the LL simulation step keys – only unclaimed arrow/Home/End presses step.

import { describe, expect, it } from 'vitest'
import { simStep } from './simKeys'

const press = (key: string, mods: Partial<{ altKey: boolean; ctrlKey: boolean; metaKey: boolean; shiftKey: boolean; defaultPrevented: boolean }> = {}) => ({
  key,
  altKey: false,
  ctrlKey: false,
  metaKey: false,
  shiftKey: false,
  defaultPrevented: false,
  ...mods,
})
const free = { consumesArrows: false }

describe('simStep', () => {
  it('steps with ← → and jumps with Home/End, clamped to the run', () => {
    expect(simStep(press('ArrowRight'), free, 3, 9)).toBe(4)
    expect(simStep(press('ArrowLeft'), free, 3, 9)).toBe(2)
    expect(simStep(press('Home'), free, 3, 9)).toBe(0)
    expect(simStep(press('End'), free, 3, 9)).toBe(9)
  })

  it('does not take the key at either end of the run (native scrolling keeps working)', () => {
    expect(simStep(press('ArrowRight'), free, 9, 9)).toBeNull()
    expect(simStep(press('ArrowLeft'), free, 0, 9)).toBeNull()
    expect(simStep(press('Home'), free, 0, 9)).toBeNull()
  })

  it('ignores keys another handler already used or a control consumes (separator, slider, radios, fields)', () => {
    expect(simStep(press('ArrowLeft', { defaultPrevented: true }), free, 3, 9)).toBeNull()
    expect(simStep(press('ArrowLeft'), { consumesArrows: true }, 3, 9)).toBeNull()
  })

  it('ignores modified keys and other keys', () => {
    expect(simStep(press('ArrowRight', { altKey: true }), free, 3, 9)).toBeNull()
    expect(simStep(press('ArrowRight', { shiftKey: true }), free, 3, 9)).toBeNull()
    expect(simStep(press('ArrowDown'), free, 3, 9)).toBeNull()
  })
})
